1	/**
2	 * The Super Productivity Witness calibration driver.
3	 *
4	 * There is no published journey for this application yet, and pinning one
5	 * before the live DOM has been read is what the TinyTranslator rounds spent
6	 * four passes undoing. This drives ONE lane of the bound production-static
7	 * output through the same host the proof will use, asks the page a list of
8	 * candidate questions, and prints every answer — including the refusals, which
9	 * are the measurement when a candidate is wrong.
10	 *
11	 * It publishes nothing, asserts nothing of its own, and is not part of any
12	 * receipt. Its only output is stdout.
13	 */
14	
15	import { appendFileSync, readFileSync } from 'node:fs';
16	import { basename, join, resolve } from 'pathe';
17	import { box, runBoxes } from '@async/witness';
18	import { joinURL } from 'ufo';
19	import { canonicalize } from '../../../core/src/receipts/canonicalize.ts';
20	import { WITNESS_ANGULAR_SUPER_PRODUCTIVITY_STYLE_PROBES } from '../../../core/src/receipts/witness-angular-super-productivity.ts';
21	import { witnessNodeFileSystem } from '../witness/node-filesystem.ts';
22	import { createPlaywrightWitnessHost } from '../witness/playwright-host.ts';
23	import { startStaticServer } from '../witness/real-app-run.ts';
24	
25	const root = resolve(import.meta.dirname, '../../../..');
26	
27	/**
28	 * The two bound lanes, exactly as the schema names them: the era lane is the
29	 * retained tree the u21 digest correction was recomputed from, and the migrated
30	 * lane is the offline-faithful rebuild u23 published.
31	 */
32	const laneRoots = {
33		baseline: join(
34			root,
35			'.versionless/cache/angular-super-productivity-v2-13-15-baseline/dist-run2',
36		),
37		migrated: join(root, '.versionless/stage/angular-super-productivity-v2-13-15-u18b/dist-25'),
38	} as const;
39	
40	const VIEWPORT = { width: 1280, height: 900 } as const;
41	
42	/**
43	 * The route the driver deep-links to.
44	 *
45	 * The bare document was measured first and records its navigation as `#/`,
46	 * which is not one of the nine routes the application declares — the router
47	 * renders the work view for it through the wildcard, and a recorded `#/` would
48	 * be a navigation the application did not name. Deep-linking the declared route
49	 * is what makes the recorded navigation a declared one.
50	 */
51	const INITIAL_ROUTE = '/#/work-view';
52	
53	/**
54	 * The candidate selectors, read out of the application's own templates rather
55	 * than guessed: the shell, the work view, the add-task surface, the task list
56	 * and the two controls the time-tracking and theme legs would be anchored on.
57	 * Each is asked for as a count, so a candidate that does not resolve reports
58	 * zero rather than ending the pass.
59	 */
60	const CANDIDATES = [
61		'main-header',
62		'main-header .project-settings-btn',
63		'mat-drawer-container',
64		'side-nav',
65		// Corrected in the u20c2a round. The first calibration pass asked for
66		// `work-view-page` because that is what the component's FILE is called; the
67		// component's own `selector` is `work-view`, and the earlier pass measured
68		// the mistake honestly as zero. The wrong spelling is kept beside the right
69		// one so the correction stays visible in the driver rather than only in a
70		// note: a reader can see both asked, and the counts say which one the
71		// application actually renders.
72		'work-view-page',
73		'work-view',
74		'.work-view-header',
75		'add-task-bar',
76		'add-task-bar input',
77		'task-list',
78		'task-list task',
79		'task',
80		'task .title',
81		'task .play-btn',
82		'task .drag-handle',
83		'.task-list-wrapper',
84		'.completed-tasks-heading',
85		'backlog',
86		'split',
87		'banner',
88		'mat-progress-bar',
89	] as const;
90	
91	/**
92	 * The observed page record out of the box receipt, narrowed to the four things
93	 * an exact inventory has to be pinned from: what the console said, what the
94	 * browser failed to fetch, what the page threw, and where it navigated.
95	 */
96	function pageSummary(receiptPath: string): unknown {
97		const receipt = JSON.parse(readFileSync(receiptPath, 'utf8')) as {
98			boxes?: Array<{ pages?: Array<Record<string, unknown>> }>;
99		};
100		const page = receipt.boxes?.[0]?.pages?.[0];
101		if (page === undefined) return null;
102		return {
103			consoleMessages: page.consoleMessages,
104			pageErrors: page.pageErrors,
105			failedRequests: page.failedRequests,
106			navigations: page.navigations,
107		};
108	}
109	
110	export async function calibrateAngularSuperProductivityLane(
111		lane: 'baseline' | 'migrated',
112	): Promise<void> {
113		const laneRoot = laneRoots[lane];
114		const receiptDir = join(
115			root,
116			'.versionless/stage/witness-angular-super-productivity-calibrate',
117			lane,
118		);
119		const staticServer = await startStaticServer(laneRoot, { profile: 'current-witness' });
120		const host = createPlaywrightWitnessHost({
121			chromiumExecutable: join(
122				root,
123				'.versionless/cache/react-boilerplate-v4/ms-playwright/chromium_headless_shell-1208/chrome-headless-shell-mac-arm64/chrome-headless-shell',
124			),
125			contextProfile: 'current-witness',
126			viewport: VIEWPORT,
127			// The reader is an opt-in and this driver opts in, because reading the
128			// store's keys either side of a create is the whole of leg (e).
129			indexedDb: 'read-keys',
130			// The application's own `index.html` links the Roboto stylesheet, so the
131			// seam is answered inside the context with an empty body exactly as the
132			// TinyTranslator vertical answers its icon stylesheet. Nothing leaves the
133			// machine, and the request is still observed.
134			transport: async () => ({
135				action: 'fulfill',
136				status: 200,
137				contentType: 'text/css',
138				body: Buffer.alloc(0),
139			}),
140		});
141		const counts: Record<string, number | string> = {};
142		let telemetry: unknown;
143		let storage: unknown;
144		let scroll: unknown;
145		const legs: Record<string, unknown> = {};
146		const definition = box(`super-productivity-calibrate-${lane}`, async (context) => {
147			const page = await context.browser.visit(joinURL(staticServer.origin, INITIAL_ROUTE));
148			for (const selector of CANDIDATES) {
149				// Asked for as zero: a candidate that genuinely resolves nothing passes
150				// and is recorded as absent, and one that resolves reports its actual
151				// count in the refusal, which is the measurement being asked for.
152				try {
153					await context.expect.page.count(page, selector, 0);
154					counts[selector] = 0;
155				} catch (error: unknown) {
156					counts[selector] = (error instanceof Error ? error.message : String(error))
157						.split('\n')[0]!
158						.trim();
159				}
160			}
161			telemetry = await host.serviceWorkerTelemetry(10_000);
162			storage = await host.browserStorageKeys();
163			scroll = await host.viewportScroll();
164	
165			// Legs (a) and (e), driven here before either is pinned into a journey.
166			// Every reading is printed rather than asserted: what this pass is for is
167			// finding out what the application does, and an assertion written before
168			// the reading exists is a guess with a stack trace.
169			const titleProbe = { group: 'task', name: '.task-title', item: '.task-title' } as const;
170			const report = async (stage: string): Promise<void> => {
171				legs[stage] = {
172					indexedDb: await host.indexedDbKeys().then(
173						(inventory) => inventory,
174						(error: unknown) => `refused: ${error instanceof Error ? error.message : String(error)}`,
175					),
176					localStorage: await host.browserStorageKeys(),
177					taskTitles: await host.groupedText(titleProbe).then(
178						(groups) => groups,
179						(error: unknown) => `refused: ${error instanceof Error ? error.message : String(error)}`,
180					),
181					scroll: await host.viewportScroll(),
182				};
183			};
184			legs['renderedStyles'] = await host.renderedStyles(
185				WITNESS_ANGULAR_SUPER_PRODUCTIVITY_STYLE_PROBES.map((probe) => ({
186					label: probe.label,
187					selector: probe.selector,
188					properties: [...probe.properties],
189				})),
190			);
191			await report('before-create');
192			await page.trackEvents('click', 'input', 'keydown');
193	
194			// PM ruling from u20c2i: drive EVERY mutation before the single leg-(e)
195			// reload. The after-reload add-task-bar hang the earlier pass hit is a
196			// property of the reloaded page, so the two creates, the timer, the drag
197			// and the settings change all happen here, and the reload is last.
198			const readIcon = async (): Promise<unknown> =>
199				host
200					.groupedText({ group: 'main-header .play-btn', name: 'mat-icon', item: 'mat-icon' } as const)
201					.then(
202						(groups) => groups.flatMap((group) => group.items),
203						(error: unknown) => `refused: ${error instanceof Error ? error.message : String(error)}`,
204					);
205			const readTitles = async (): Promise<unknown> =>
206				host.groupedText({ group: 'task', name: '.task-title', item: '.task-title' } as const).then(
207					(groups) => groups.map((group) => group.name),
208					(error: unknown) => `refused: ${error instanceof Error ? error.message : String(error)}`,
209				);
210			const cb: Record<string, unknown> = {};
211			// Assigned before the drives so a step that throws still leaves every
212			// reading taken up to that point in the printed record, rather than losing
213			// the whole block to one refusal.
214			legs['legs-c-b-d'] = cb;
215	
216			await page.type('add-task-bar input', 'Witness calibration task', { redact: false });
217			await page.press('add-task-bar input', 'Enter');
218			await new Promise<void>((settle) => void setTimeout(settle, 1_500));
219			cb['titles-after-first-create'] = await readTitles();
220			await page.type('add-task-bar input', 'Witness calibration task two', { redact: false });
221			await page.press('add-task-bar input', 'Enter');
222			await new Promise<void>((settle) => void setTimeout(settle, 1_000));
223			cb['titles-after-second-create'] = await readTitles();
224			for (const selector of [
225				'main-header .play-btn',
226				'task .play-icon-indicator',
227				'task .time-wrapper',
228				'task .time-wrapper .time-val',
229				'task .drag-handle',
230				'task .drag-handle.handle-par',
231				'.task-list-inner',
232				'.task-list-inner[dragula]',
233				'task .start-task-btn',
234			]) {
235				try {
236					await context.expect.page.count(page, selector, 0);
237					cb[`count:${selector}`] = 0;
238				} catch (error: unknown) {
239					cb[`count:${selector}`] = (error instanceof Error ? error.message : String(error))
240						.split('\n')[0]!
241						.trim();
242				}
243			}
244			// Leg (c), re-anchored (u20c2j): the hover-gated per-task `.start-task-btn`
245			// is not visible to a click, so the timer is driven through the header's own
246			// global play button, whose `mat-icon` flips play_arrow→pause on start and
247			// back on stop. Every reading — the icon, the per-task current marker and the
248			// store keys — is taken before start, after start and after stop.
249			const readStoreKeys = async (): Promise<unknown> =>
250				host.indexedDbKeys().then(
251					(inv) =>
252						inv.databases
253							.find((d) => d.name === 'SUP')
254							?.stores.find((s) => s.name === 'SUP_STORE')
255							?.keys.map((k) => k.key) ?? 'no SUP_STORE',
256					(e: unknown) => `refused: ${e instanceof Error ? e.message : String(e)}`,
257				);
258			const readCurrentCount = async (selector: string): Promise<number | string> => {
259				try {
260					await context.expect.page.count(page, selector, 0);
261					return 0;
262				} catch (error: unknown) {
263					return (error instanceof Error ? error.message : String(error)).split('\n')[0]!.trim();
264				}
265			};
266			cb['icon-before-start'] = await readIcon();
267			cb['current-before-start'] = await readCurrentCount('task.isCurrent');
268			cb['store-before-start'] = await readStoreKeys();
269			try {
270				await page.click('main-header .play-btn');
271				await new Promise<void>((settle) => void setTimeout(settle, 2_000));
272				cb['icon-after-header-start'] = await readIcon();
273				cb['current-after-header-start'] = await readCurrentCount('task.isCurrent');
274				cb['store-after-header-start'] = await readStoreKeys();
275				await page.click('main-header .play-btn');
276				await new Promise<void>((settle) => void setTimeout(settle, 2_000));
277				cb['icon-after-header-stop'] = await readIcon();
278				cb['current-after-header-stop'] = await readCurrentCount('task.isCurrent');
279				cb['store-after-header-stop'] = await readStoreKeys();
280			} catch (error: unknown) {
281				cb['time-tracking-error'] = error instanceof Error ? error.message : String(error);
282			}
283			// Leg (b): the dragula reorder, initiated on the parent drag handle. Two
284			// strategies are tried in one pass: drop onto the second task's handle,
285			// and — if the order did not change — drag the second task's handle UP
286			// onto the first. Every reading is printed.
287			cb['order-before-drag'] = await readTitles();
288			try {
289				await page.drag(
290					'task-list:first-of-type task:nth-of-type(1) .drag-handle.handle-par',
291					'task-list:first-of-type task:nth-of-type(2)',
292					{ steps: 30 },
293				);
294				await new Promise<void>((settle) => void setTimeout(settle, 1_200));
295				cb['order-after-drag-down'] = await readTitles();
296				const afterDown = (await readTitles()) as string[];
297				if (
298					Array.isArray(afterDown) &&
299					afterDown.join('\n') === (cb['order-before-drag'] as string[]).join('\n')
300				) {
301					await page.drag(
302						'task-list:first-of-type task:nth-of-type(2) .drag-handle.handle-par',
303						'task-list:first-of-type task:nth-of-type(1)',
304						{ steps: 30 },
305					);
306					await new Promise<void>((settle) => void setTimeout(settle, 1_200));
307					cb['order-after-drag-up'] = await readTitles();
308				}
309				cb['indexeddb-after-drag'] = await host
310					.indexedDbKeys()
311					.then((i) => i, (e: unknown) => `refused: ${e instanceof Error ? e.message : String(e)}`);
312			} catch (error: unknown) {
313				cb['drag-error'] = error instanceof Error ? error.message : String(error);
314			}
315	
316			// Leg (d): settings-change. The app exposes NO dark-theme UI control in
317			// v2.13.15 (the isDarkMode formly field is commented out), so the real
318			// controls driven are: a second project created through the side-nav
319			// addProject() dialog and switched to, then its PRIMARY theme colour
320			// changed through the /project-settings formly config-section save, and
321			// one keyboard shortcut. Every selector is asked as a count first, the
322			// surfaces are exercised, and the palette custom properties and the
323			// shell's current-project title are read before/after. Printed, never
324			// asserted.
325			const dd: Record<string, unknown> = {};
326			legs['leg-d'] = dd;
327			const paletteProps = [
328				'--palette-primary-500',
329				'--palette-accent-500',
330				'--palette-primary-400',
331				'--c-primary',
332				'--c-accent',
333			];
334			const readPalette = async (): Promise<unknown> =>
335				host
336					.renderedStyles([
337						{ label: 'body-palette', selector: 'body', properties: [...paletteProps] },
338						{ label: 'drawer-palette', selector: 'mat-drawer-container', properties: [...paletteProps] },
339					])
340					.then(
341						(probes) =>
342							probes.map((p) => ({ label: p.label, properties: p.properties })),
343						(e: unknown) => `refused: ${e instanceof Error ? e.message : String(e)}`,
344					);
345			// The box PageHandle exposes NO evaluate/fill primitive, so the count is
346			// read out of the retry-until-timeout assertion's refusal: asking for 0
347			// and parsing the observed N. A present element costs one assertion
348			// window, so this is used sparingly.
349			const readCount = async (selector: string): Promise<number | string> => {
350				try {
351					await context.expect.page.count(page, selector, 0);
352					return 0;
353				} catch (error: unknown) {
354					const line = (error instanceof Error ? error.message : String(error))
355						.split('\n')[0]!
356						.trim();
357					const m = line.match(/observed (\d+)/);
358					return m ? Number(m[1]) : line;
359				}
360			};
361			const readCurrentProjectTitle = async (): Promise<unknown> =>
362				host
363					.groupedText({
364						group: 'main-header',
365						name: '.current-project-title',
366						item: '.current-project-title',
367					} as const)
368					.then(
369						(g) => g.map((x) => x.name),
370						(e: unknown) => `refused: ${e instanceof Error ? e.message : String(e)}`,
371					);
372			const readProjectTitles = async (): Promise<unknown> =>
373				host
374					.groupedText({
375						group: 'side-nav .project',
376						name: 'button[mat-menu-item]',
377						item: 'button[mat-menu-item]',
378					} as const)
379					.then(
380						(g) => g.map((x) => x.name),
381						(e: unknown) => `refused: ${e instanceof Error ? e.message : String(e)}`,
382					);
383			const ckPath =
384				process.env.LEG_D_CK ??
385				join(receiptDir, 'leg-d-checkpoints.log');
386			const ck = (m: string): void => {
387				try {
388					appendFileSync(ckPath, `${new Date().toISOString()} [${lane}] ${m}\n`);
389				} catch {
390					/* diagnostic only */
391				}
392			};
393			ck('leg-d reached (before before-reads)');
394			// The number actually present, parsed out of the count refusal, so an
395			// interaction is only driven against an element the page really has —
396			// char-by-char typing against a missing element would burn one interaction
397			// timeout per character.
398			const actualCount = async (selector: string): Promise<number> => {
399				const r = await readCount(selector);
400				return typeof r === 'number' ? r : -1;
401			};
402			// Attempt the click with a bounded timeout and report the outcome, rather
403			// than pre-checking with a full assertion window per selector.
404			const clickIfPresent = async (selector: string): Promise<string> => {
405				try {
406					await page.click(selector, { timeoutMs: 4_000 });
407					return 'clicked';
408				} catch (error: unknown) {
409					const msg = (error instanceof Error ? error.message : String(error)).split('\n')[0]!;
410					ck(`click failed: ${selector} — ${msg}`);
411					return `failed: ${msg}`;
412				}
413			};
414			try {
415				dd['palette-before'] = await readPalette();
416				dd['current-project-title-before'] = await readCurrentProjectTitle();
417				dd['project-titles-before'] = await readProjectTitles();
418				ck('opening addProject dialog');
419	
420				// (d.1) Open the addProject() dialog from the side-nav.
421				dd['add-clicked'] = await clickIfPresent('section.projects > button[mat-menu-item]');
422				await new Promise<void>((settle) => void setTimeout(settle, 1_200));
423				dd['dialog-count'] = await readCount('dialog-create-project');
424				ck('dialog opened, setting title');
425				// Type a title into the formly title input (a TEXT input, so char-press
426				// works) — only if present, so a missing input costs one bounded count
427				// rather than one interaction timeout per character.
428				const titleInput = 'dialog-create-project input:not([type=color])';
429				const titleCount = await actualCount(titleInput);
430				dd['title-input-count'] = titleCount;
431				if (titleCount > 0) {
432					try {
433						await page.type(titleInput, 'Witness leg-d project', { redact: false, timeoutMs: 4_000 });
434						dd['title-typed'] = true;
435					} catch (error: unknown) {
436						dd['title-typed'] = `failed: ${error instanceof Error ? error.message : String(error)}`;
437					}
438					await new Promise<void>((settle) => void setTimeout(settle, 500));
439					ck('title set, clicking save');
440					dd['save-clicked'] = await clickIfPresent('dialog-create-project button[type=submit]');
441					await new Promise<void>((settle) => void setTimeout(settle, 1_500));
442				} else {
443					dd['title-input'] = 'absent';
444				}
445				dd['dialog-count-after-save'] = await readCount('dialog-create-project');
446				dd['project-titles-after-add'] = await readProjectTitles();
447				dd['side-nav-project-count-after-add'] = await readCount('side-nav .project');
448				ck('switching to new project');
449	
450				// (d.2) Switch to the new (second) project via its side-nav button.
451				dd['switch-clicked'] = await clickIfPresent(
452					'side-nav .project:nth-of-type(2) > button[mat-menu-item]',
453				);
454				await new Promise<void>((settle) => void setTimeout(settle, 1_500));
455				dd['current-project-title-after-switch'] = await readCurrentProjectTitle();
456				dd['route-after-switch'] = 'see page navigations';
457				dd['palette-after-switch'] = await readPalette();
458				ck('navigating to project-settings');
459	
460				// (d.3) Go to the current project's settings via the header control.
461				dd['settings-nav-clicked'] = await clickIfPresent('main-header .project-settings-btn');
462				await new Promise<void>((settle) => void setTimeout(settle, 1_500));
463				dd['route-after-settings-nav'] = 'see page navigations';
464				dd['config-section-count'] = await readCount('section.config-section');
465				ck('expanding theme config-section');
466				// Expand the 2nd config-section (the collapsible theme form).
467				dd['expand-clicked'] = await clickIfPresent(
468					'section.config-section:nth-of-type(2) .collapsible-title',
469				);
470				await new Promise<void>((settle) => void setTimeout(settle, 1_200));
471				dd['palette-before-save'] = await readPalette();
472				ck('setting colour input value');
473				// The box PageHandle has no fill/evaluate. Test whether ANY available
474				// primitive can change a native input[type=color]: char-press typing,
475				// and clicking-then-pressing. Palette is measured after each so the
476				// question "can the witness drive this control at all" is answered by
477				// measurement rather than assumed.
478				const colorInput = 'section.config-section:nth-of-type(2) input[type=color]';
479				const colorCount = await actualCount(colorInput);
480				dd['color-input-count'] = colorCount;
481				if (colorCount > 0) {
482					try {
483						await page.type(colorInput, '#ff0000', { redact: false, timeoutMs: 4_000 });
484						dd['color-type-attempt'] = 'typed';
485					} catch (error: unknown) {
486						dd['color-type-attempt'] = `failed: ${error instanceof Error ? error.message : String(error)}`;
487					}
488					await new Promise<void>((settle) => void setTimeout(settle, 400));
489					dd['palette-after-color-type'] = await readPalette();
490					try {
491						await page.click(colorInput, { timeoutMs: 4_000 });
492						for (const key of ['ArrowUp', 'ArrowUp', 'PageUp']) {
493							await page.press(colorInput, key, { timeoutMs: 3_000 });
494						}
495						dd['color-press-attempt'] = 'pressed';
496					} catch (error: unknown) {
497						dd['color-press-attempt'] = `failed: ${error instanceof Error ? error.message : String(error)}`;
498					}
499					await new Promise<void>((settle) => void setTimeout(settle, 400));
500					dd['palette-after-color-press'] = await readPalette();
501					ck('clicking theme submit');
502					dd['save-color-clicked'] = await clickIfPresent(
503						'section.config-section:nth-of-type(2) .submit-button',
504					);
505					await new Promise<void>((settle) => void setTimeout(settle, 1_800));
506				} else {
507					dd['color-input'] = 'absent';
508				}
509				dd['palette-after-save'] = await readPalette();
510	
511				// (d.4) A keyboard shortcut. `w` (goToWorkView) and `b` (toggleBacklog)
512				// are both measured; the observable effect in this DOM state decides
513				// which the journey anchors on.
514				ck('keyboard shortcuts');
515				dd['route-before-shortcut'] = 'see page navigations';
516				await page.press('body', 'w');
517				await new Promise<void>((settle) => void setTimeout(settle, 1_000));
518				dd['route-after-w'] = 'see page navigations';
519				dd['host-tag-after-w'] = await readCount('work-view');
520				dd['split-count-before-b'] = await readCount('split');
521				await page.press('body', 'b');
522				await new Promise<void>((settle) => void setTimeout(settle, 1_000));
523				dd['route-after-b'] = 'see page navigations';
524				dd['split-count-after-b'] = await readCount('split');
525				dd['backlog-count-after-b'] = await readCount('backlog');
526				ck('leg-d done');
527			} catch (error: unknown) {
528				dd['leg-d-error'] = error instanceof Error ? error.message : String(error);
529				ck(`error: ${error instanceof Error ? error.message : String(error)}`);
530			}
531			cb['pageErrors-during-cb'] = 'see page summary';
532	
533			// (e) The single reload, LAST, after every mutation has been driven.
534			await report('after-create');
535			await page.reload();
536			await new Promise<void>((settle) => void setTimeout(settle, 2_500));
537			await report('after-reload');
538			legs['after-reload-telemetry'] = await host.serviceWorkerTelemetry(10_000);
539			for (const selector of ['task-list', 'task-list task', 'task', 'task .task-title']) {
540				try {
541					await context.expect.page.count(page, selector, 0);
542					legs[`count:${selector}`] = 0;
543				} catch (error: unknown) {
544					legs[`count:${selector}`] = (error instanceof Error ? error.message : String(error))
545						.split('\n')[0]!
546						.trim();
547				}
548			}
549			await context.receipt.capture('calibration-complete');
550		});
551		let status = 'unknown';
552		let failure = '';
553		let receiptPath = '';
554		try {
555			const result = await runBoxes({
556				root: laneRoot,
557				boxes: [
558					{
559						file: join(laneRoot, 'versionless-runtime.box.ts'),
560						relativeFile: 'versionless-runtime.box.ts',
561						exportName: 'default',
562						box: definition,
563					},
564				],
565				receiptDir,
566				assertionTimeoutMs: 10_000,
567				fileSystem: witnessNodeFileSystem,
568				browser: host.browser,
569				headless: true,
570			});
571			status = result.status;
572			failure = result.boxes[0]?.error?.message ?? '';
573			receiptPath = result.receiptPath;
574		} finally {
575			await staticServer.close();
576		}
577		process.stdout.write(
578			`${canonicalize({
579				lane,
580				status,
581				failure,
582				receiptPath,
583				counts,
584				telemetry,
585				storage,
586				scroll,
587				legs,
588				page: receiptPath === '' ? null : pageSummary(receiptPath),
589				requestOutcomes: host.requestOutcomes(),
590				staticPaths: staticServer.requests(),
591			})}\n`,
592		);
593	}
594	
595	export async function main(args = process.argv.slice(2)): Promise<void> {
596		const lane = args[0];
597		if (lane !== 'baseline' && lane !== 'migrated')
598			throw new Error('Super Productivity calibration requires a lane: baseline or migrated');
599		await calibrateAngularSuperProductivityLane(lane);
600	}
601	
602	if (basename(process.argv[1] ?? '') === 'angular-super-productivity-calibrate-run.ts')
603		main().catch((error: unknown) => {
604			process.stderr.write(`${error instanceof Error ? error.message : String(error)}\n`);
605			process.exitCode = 1;
606		});
607

